INSERT INTO verification_results WITH q(c0) AS (SELECT id FROM Fact WHERE x = 1) SELECT 1 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT id FROM Fact WHERE x = 1 AND y = 1) SELECT 2 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT id FROM Fact WHERE x = 1 OR y = 2) SELECT 3 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT id FROM Fact WHERE NOT (id < 100)) SELECT 4 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT id FROM Fact WHERE id >= 200 AND id < 220) SELECT 5 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT id FROM Fact WHERE id <> 250 ORDER BY id DESC LIMIT 5) SELECT 6 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT DISTINCT x FROM Fact ORDER BY x) SELECT 7 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1) AS (SELECT x, COUNT(*) AS n FROM Fact GROUP BY x HAVING x > 4 ORDER BY x) SELECT 8 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1) AS (SELECT y, SUM(id) AS n FROM Fact GROUP BY y HAVING SUM(id) > 8000 ORDER BY y) SELECT 9 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT COUNT(*) AS n FROM Fact WHERE id = 999) SELECT 10 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT f.id FROM Fact f JOIN Other o ON f.id = o.id) SELECT 11 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1,c2,c3,c4,c5,c6,c7,c8,c9,c10) AS (SELECT f.id, f.p0, f.p1, f.p2, f.p3, f.p4, o.p0, o.p1, o.p2, o.p3, o.p4 FROM Fact f JOIN Other o ON f.id = o.id WHERE f.x = 1 AND f.y = 1) SELECT 12 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1) AS (SELECT t.id, r.id FROM Team t JOIN Region r ON t.region = r.id WHERE r.id = 1) SELECT 13 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1) AS (SELECT t.id, r.id FROM Team t, Region r WHERE t.region = r.id AND r.id = 1) SELECT 14 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1,c2) AS (SELECT t.id, r.id, c.label FROM Team t JOIN Region r ON t.region = r.id JOIN Country c ON r.country = c.id) SELECT 15 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1,c2,c3) AS (SELECT f.id, t.id, r.id, c.label FROM Fact f JOIN Team t ON f.x = t.id JOIN Region r ON t.region = r.id JOIN Country c ON r.country = c.id WHERE f.id < 30) SELECT 16 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT f.id FROM Fact f WHERE f.id < 6 UNION SELECT t.id FROM Team t) SELECT 17 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT t.id FROM Team t UNION ALL SELECT r.id FROM Region r) SELECT 18 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT t.id FROM Team t INTERSECT SELECT r.id FROM Region r) SELECT 19 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT t.id FROM Team t EXCEPT SELECT r.id FROM Region r) SELECT 20 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT u.id FROM (SELECT id FROM Team UNION ALL SELECT id FROM Region) AS u WHERE u.id = 2) SELECT 21 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1) AS (SELECT u.x, u.n FROM (SELECT x, COUNT(*) AS n FROM Fact GROUP BY x) AS u WHERE u.x = 7) SELECT 22 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0) AS (SELECT c.label FROM Country c ORDER BY c.id DESC) SELECT 23 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
INSERT INTO verification_results WITH q(c0,c1) AS (SELECT a.id, b.region FROM Team a JOIN Team b ON a.region = b.region WHERE a.id < b.id) SELECT 24 AS query_id, COUNT(*) AS row_count, COALESCE(jsonb_agg(to_jsonb(q) ORDER BY to_jsonb(q)), '[]'::jsonb) AS rows FROM q;
