CREATE TEMP TABLE verification_results (query_id INT, row_count BIGINT, rows JSONB);

CREATE TEMP TABLE Fact (id INT, x INT, y INT, p0 VARCHAR(240), p1 VARCHAR(240), p2 VARCHAR(240), p3 VARCHAR(240), p4 VARCHAR(240));


CREATE TEMP TABLE Other (id INT, p0 VARCHAR(240), p1 VARCHAR(240), p2 VARCHAR(240), p3 VARCHAR(240), p4 VARCHAR(240));


CREATE TEMP TABLE Team (id INT, region INT);


CREATE TEMP TABLE Region (id INT, country INT);


CREATE TEMP TABLE Country (id INT, label VARCHAR(20));



























SELECT * FROM verification_results ORDER BY query_id;
